inline gf_status invoke_windows_paint_endpoint_submit_bgra(const AbiTables& tables, Arguments& arguments) {
    const uint64_t compatibility_handle = arguments.u64(0U);
    const uint32_t width = arguments.u32(1U);
    const uint32_t height = arguments.u32(2U);
    const uint64_t row_bytes = arguments.u64(3U);
    const uint8_t* const pixels = arguments.bytes_input<uint8_t>(4U);
    const gf_status status = tables.windows_paint_endpoint.submit_bgra(compatibility_handle, width, height, row_bytes, pixels);
    return status;
}

// windows_paint_endpoint.touch
inline gf_status invoke_windows_paint_endpoint_touch(const AbiTables& tables, Arguments& arguments) {
    const gf_paint_endpoint endpoint = static_cast<gf_paint_endpoint>(arguments.u64(0U));
    const uint32_t explicit_boundary = arguments.u32(1U);
    const gf_status status = tables.windows_paint_endpoint.touch(endpoint, explicit_boundary);
    return status;
}

// Slots no block calls, and why:
//   application.close: ends the process's one application
//   application.create: the application is one per process, so no input may make it
//   bindings.set_provider: takes code or a context pointer
//   classes.create: takes code or a context pointer
//   content.sink_wait_for_request: waits for a request that never comes
//   content.start_hosted: starts a process
//   content.start_program: starts a process
//   custom_controls.create: takes code or a context pointer
//   diagnostics.raise_native_exception: raises a native exception on purpose
//   dispatch.begin_invoke: takes code or a context pointer
//   events.subscribe: takes code or a context pointer
//   events.subscribe_property: takes code or a context pointer
//   help.export_template: writes a file
//   help.show: opens a help window
//   help.show_navigator: opens a help window or the system browser
//   help.show_popup: opens a host popup
//   host.read_clipboard_text: reads the machine's clipboard
//   host.set_cursor: changes the machine's pointer
//   host.show_dialog: opens a modal system dialog
//   host.write_clipboard_text: replaces the machine's clipboard
//   overlays.open_anchored: takes code or a context pointer
//   rules.add: takes code or a context pointer
//   subsurfaces.set_content: takes code or a context pointer
//   themes.install: writes the user's theme directory
//   themes.remove: removes from the user's theme directory
//   windows.run: blocks until the window closes (a host run)
//   windows.show_modal: blocks until the modal window closes
//   windows.show_owned: opens a host window

